    "    z[\"value\"] : None\n"
    "    if not at(p, \";\"):\n"
    "        z[\"value\"] : parse_expr(p)\n"
    "    need(p, \";\")\n"
    "    return z\n"
    "\n"
    "def parse_if(p):\n"
    "    x : take(p)\n"
    "    need(p, \"(\")\n"
    "    test : parse_expr(p)\n"
    "    need(p, \")\")\n"
    "    z : node(\"If\", x)\n"
    "    z[\"test\"] : test\n"
    "    z[\"body\"] : parse_block_or_stmt(p)\n"
    "    z[\"elifs\"] : []\n"
    "    z[\"orelse\"] : []\n"
    "    while at(p, \"else\") and peekn(p, 1)[\"text\"] = \"if\":\n"
    "        e : take(p)\n"
    "        take(p)\n"
    "        need(p, \"(\")\n"
    "        et : parse_expr(p)\n"
    "        need(p, \")\")\n"
    "        eb : parse_block_or_stmt(p)\n"
    "        z[\"elifs\"].append({\"test\":et, \"body\":eb, \"line\":e[\"line\"], \"col\":e[\"col\"]})\n"
    "    if at(p, \"else\"):\n"
    "        take(p)\n"
    "        z[\"orelse\"] : parse_block_or_stmt(p)\n"
    "    return z\n"
    "\n"
    "def parse_while(p):\n"
    "    x : take(p)\n"
    "    need(p, \"(\")\n"
    "    t : parse_expr(p)\n"
    "    need(p, \")\")\n"
    "    z : node(\"While\", x)\n"
    "    z[\"test\"] : t\n"
    "    z[\"body\"] : parse_block_or_stmt(p)\n"
    "    return z\n"
    "\n"
    "def parse_for(p):\n"
    "    x : take(p)\n"
    "    need(p, \"(\")\n"
    "    # Enhanced for: for (Type name : expr)\n"
    "    save : p[\"pos\"]\n"
    "    if skip_type(p) and kind(p, \"NAME\") and not is_kw(peek(p)[\"text\"]) and peekn(p, 1)[\"text\"] = \":\":\n"
    "        a : take(p)\n"
    "        ident(p, a)\n"
    "        need(p, \":\")\n"
    "        it : parse_expr(p)\n"
    "        need(p, \")\")\n"
    "        z : node(\"For\", x)\n"
    "        tgt : node(\"Name\", a)\n"
    "        tgt[\"value\"] : a[\"text\"]\n"
    "        z[\"target\"] : tgt\n"
    "        z[\"iter\"] : it\n"
    "        z[\"body\"] : parse_block_or_stmt(p)\n"
    "        return z\n"
    "    p[\"pos\"] : save\n"
    "    init : None\n"
    "    if not at(p, \";\"):\n"
    "        init : parse_for_clause(p)\n"
    "    need(p, \";\")\n"
    "    cond : None\n"
    "    if not at(p, \";\"):\n"
    "        cond : parse_expr(p)\n"
    "    need(p, \";\")\n"
    "    upd : None\n"
    "    if not at(p, \")\"):\n"
    "        upd : parse_assign_no_semi(p)\n"
    "    need(p, \")\")\n"
    "    body : parse_block_or_stmt(p)\n"
    "    w : node(\"While\", x)\n"
    "    if cond = None:\n"
    "        tc : node(\"Const\", x)\n"
    "        tc[\"value\"] : \"True\"\n"
    "        tc[\"kind\"] : \"number\"\n"
    "        w[\"test\"] : tc\n"
    "    else:\n"
    "        w[\"test\"] : cond\n"
    "    b2 : []\n"
    "    for s in body:\n"
    "        b2.append(s)\n"
    "    if upd != None:\n"
    "        b2.append(upd)\n"
    "    w[\"body\"] : b2\n"
    "    seq : node(\"Seq\", x)\n"
    "    stmts : []\n"
    "    if init != None:\n"
    "        stmts.append(init)\n"
    "    stmts.append(w)\n"
    "    seq[\"body\"] : stmts\n"
    "    return seq\n"
    "\n"
    "def parse_for_clause(p):\n"
    "    x : peek(p)\n"
    "    save : p[\"pos\"]\n"
    "    if skip_type(p) and kind(p, \"NAME\") and not is_kw(peek(p)[\"text\"]) and peekn(p, 1)[\"text\"] = \"=\":\n"
    "        nt : take(p)\n"
    "        ident(p, nt)\n"
    "        need(p, \"=\")\n"
    "        v : parse_expr(p)\n"
    "        z : node(\"Assign\", x)\n"
    "        tg : node(\"Name\", x)\n"
    "        tg[\"value\"] : nt[\"text\"]\n"
    "        z[\"target\"] : tg\n"
    "        z[\"value\"] : v\n"
    "        return z\n"
    "    p[\"pos\"] : save\n"
    "    return parse_assign_no_semi(p)\n"
    "\n"
    "def parse_assign_no_semi(p):\n"
    "    x : peek(p)\n"
    "    left : parse_expr(p)\n"
    "    tt : peek(p)[\"text\"]\n"
    "    if tt = \"=\":\n"
    "        take(p)\n"
    "        val : parse_expr(p)\n"
    "        z : node(\"Assign\", x)\n"
    "        z[\"target\"] : left\n"
    "        z[\"value\"] : val\n"
    "        validate_target(p, left)\n"
    "        return z\n"
    "    if tt in [\"+=\", \"-=\", \"*=\", \"/=\"]:\n"
    "        op : take(p)[\"text\"]\n"
    "        z : node(\"AugAssign\", x)\n"
    "        z[\"target\"] : left\n"
    "        validate_target(p, left)\n"
    "        z[\"op\"] : op\n"
    "        z[\"value\"] : parse_expr(p)\n"
    "        return z\n"
    "    if tt = \"++\" or tt = \"--\":\n"
    "        take(p)\n"
    "        z : node(\"AugAssign\", x)\n"
    "        z[\"target\"] : left\n"
    "        validate_target(p, left)\n"
    "        z[\"op\"] : \"+=\" if tt = \"++\" else \"-=\"\n"
    "        one : node(\"Const\", x)\n"
    "        one[\"value\"] : \"1\"\n"
    "        one[\"kind\"] : \"number\"\n"
    "        z[\"value\"] : one\n"
    "        return z\n"
    "    z : node(\"Expr\", x)\n"
    "    z[\"value\"] : left\n"
    "    return z\n"
    "\n"
    "def parse_expr_stmt(p):\n"
    "    z : parse_assign_no_semi(p)\n"
    "    need(p, \";\")\n"
    "    return z\n"
    "\n"
    "def validate_target(p, x):\n"
    "    if x[\"t\"] = \"Name\" or x[\"t\"] = \"Attr\" or x[\"t\"] = \"Subscript\":\n"
    "        return\n"
    "    fail(p, \"unsupported assignment target\", x)\n"
    "\n"
    "def is_lambda_ahead(p):\n"
    "    if kind(p, \"NAME\") and not is_kw(peek(p)[\"text\"]) and peekn(p, 1)[\"text\"] = \"->\":\n"
    "        return True\n"
    "    if peek(p)[\"text\"] = \"(\":\n"
    "        depth : 0\n"
    "        j : 0\n"
    "        while True:\n"
    "            t : peekn(p, j)\n"
    "            if t[\"kind\"] = \"END\":\n"
    "                return False\n"
    "            tx : t[\"text\"]\n"
    "            if tx = \"(\":\n"
    "                depth += 1\n"
    "            elif tx = \")\":\n"
    "                depth += -1\n"
    "                if depth = 0:\n"
    "                    return peekn(p, j + 1)[\"text\"] = \"->\"\n"
    "            j += 1\n"
    "    return False\n"
    "\n"
    "def parse_expr(p):\n"
    "    if is_lambda_ahead(p):\n"
    "        return parse_lambda(p)\n"
    "    return parse_ternary(p)\n"
    "\n"
    "def parse_lambda_param(p):\n"
    "    if kind(p, \"NAME\") and peekn(p, 1)[\"kind\"] = \"NAME\":\n"
    "        skip_type(p)\n"
    "    a : need_kind(p, \"NAME\")\n"
    "    return ident(p, a)\n"
    "\n"
    "def parse_lambda(p):\n"
    "    x : peek(p)\n"
    "    args : []\n"
    "    if at(p, \"(\"):\n"
    "        take(p)\n"
    "        if not at(p, \")\"):\n"
    "            while True:\n"
    "                args.append(parse_lambda_param(p))\n"
    "                if not at(p, \",\"):\n"
    "                    break\n"
    "                take(p)\n"
    "        need(p, \")\")\n"
    "    else:\n"
    "        a : need_kind(p, \"NAME\")\n"
    "        args.append(ident(p, a))\n"
    "    need(p, \"->\")\n"
    "    if at(p, \"{\"):\n"
    "        fail(p, \"block-bodied lambdas are unsupported\", peek(p))\n"
    "    if len(args) > 1:\n"
    "        fail(p, \"multi-argument lambdas are unsupported\", x)\n"
    "    z : node(\"Lambda\", x)\n"
    "    z[\"args\"] : args\n"
    "    z[\"body\"] : parse_expr(p)\n"
    "    return z\n"
    "\n"
    "def parse_ternary(p):\n"
    "    c : parse_or(p)\n"
    "    if at(p, \"?\"):\n"
    "        take(p)\n"
    "        a : parse_expr(p)\n"
    "        need(p, \":\")\n"
    "        b : parse_expr(p)\n"
    "        z : node(\"IfExp\", c)\n"
    "        z[\"body\"] : a\n"
    "        z[\"test\"] : c\n"
    "        z[\"orelse\"] : b\n"
    "        return z\n"
    "    return c\n"
    "\n"
    "def parse_or(p):\n"
    "    xs : [parse_and(p)]\n"
    "    x : xs[0]\n"
    "    while at(p, \"||\"):\n"
    "        take(p)\n"
    "        xs.append(parse_and(p))\n"
    "    if len(xs) = 1:\n"
    "        return x\n"
    "    z : node(\"BoolOp\", x)\n"
    "    z[\"op\"] : \"or\"\n"
    "    z[\"values\"] : xs\n"
    "    return z\n"
    "\n"
    "def parse_and(p):\n"
    "    xs : [parse_compare(p)]\n"
    "    x : xs[0]\n"
    "    while at(p, \"&&\"):\n"
    "        take(p)\n"
    "        xs.append(parse_compare(p))\n"
    "    if len(xs) = 1:\n"
    "        return x\n"
    "    z : node(\"BoolOp\", x)\n"
    "    z[\"op\"] : \"and\"\n"
    "    z[\"values\"] : xs\n"
    "    return z\n"
    "\n"
    "def parse_compare(p):\n"
    "    left : parse_add(p)\n"
    "    if peek(p)[\"text\"] in [\"==\", \"!=\", \"<\", \"<=\", \">\", \">=\"]:\n"
    "        op : take(p)[\"text\"]\n"
    "        right : parse_add(p)\n"
    "        z : node(\"Compare\", left)\n"
    "        z[\"left\"] : left\n"
    "        z[\"op\"] : op\n"
    "        z[\"right\"] : right\n"
    "        return z\n"
    "    return left\n"
    "\n"
    "def parse_add(p):\n"
    "    z : parse_mul(p)\n"
    "    while peek(p)[\"text\"] = \"+\" or peek(p)[\"text\"] = \"-\":\n"
    "        op : take(p)[\"text\"]\n"
    "        q : node(\"BinOp\", z)\n"
    "        q[\"left\"] : z\n"
    "        q[\"op\"] : op\n"
    "        q[\"right\"] : parse_mul(p)\n"
    "        z : q\n"
    "    return z\n"
    "\n"
    "def parse_mul(p):\n"
    "    z : parse_unary(p)\n"
    "    while peek(p)[\"text\"] in [\"*\", \"/\", \"%\"]:\n"
    "        op : take(p)[\"text\"]\n"
    "        q : node(\"BinOp\", z)\n"
    "        q[\"left\"] : z\n"
    "        q[\"op\"] : op\n"
    "        q[\"right\"] : parse_unary(p)\n"
    "        z : q\n"
    "    return z\n"
    "\n"
    "def parse_unary(p):\n"
    "    tt : peek(p)[\"text\"]\n"
    "    if tt = \"!\":\n"
    "        x : take(p)\n"
    "        z : node(\"Unary\", x)\n"
    "        z[\"op\"] : \"not\"\n"
    "        z[\"value\"] : parse_unary(p)\n"
    "        return z\n"
    "    if tt = \"-\":\n"
    "        x : take(p)\n"
    "        z : node(\"Unary\", x)\n"
    "        z[\"op\"] : \"-\"\n"
    "        z[\"value\"] : parse_unary(p)\n"
    "        return z\n"
    "    if tt = \"+\":\n"
    "        fail(p, \"unary plus is unsupported\", peek(p))\n"
    "    if tt = \"++\" or tt = \"--\":\n"
    "        fail(p, \"prefix increment is unsupported\", peek(p))\n"
    "    return parse_postfix(p)\n"
    "\n"
    "def parse_postfix(p):\n"
    "    z : parse_atom(p)\n"
    "    while True:\n"
    "        if at(p, \".\"):\n"
    "            x : take(p)\n"
    "            a : need_kind(p, \"NAME\")\n"
    "            q : node(\"Attr\", x)\n"
    "            q[\"value\"] : z\n"
    "            q[\"attr\"] : a[\"text\"]\n"
    "            z : q\n"
    "        elif at(p, \"(\"):\n"
    "            x : take(p)\n"
    "            q : node(\"Call\", x)\n"
    "            q[\"func\"] : z\n"
    "            q[\"args\"] : []\n"
    "            q[\"kwargs\"] : []\n"
    "            if not at(p, \")\"):\n"
    "                while True:\n"
    "                    q[\"args\"].append(parse_expr(p))\n"
    "                    if not at(p, \",\"):\n"
    "                        break\n"
    "                    take(p)\n"
    "            need(p, \")\")\n"
    "            z : q\n"
    "        elif at(p, \"[\"):\n"
    "            x : take(p)\n"
    "            q : node(\"Subscript\", x)\n"
    "            q[\"value\"] : z\n"
    "            q[\"slice\"] : parse_index(p)\n"
    "            need(p, \"]\")\n"
    "            z : q\n"
    "        else:\n"
    "            break\n"
    "    return z\n"
    "\n"
    "def parse_index(p):\n"
    "    x : peek(p)\n"
    "    lower : None\n"
    "    if not at(p, \"]\"):\n"
    "        lower : parse_expr(p)\n"
    "    return lower\n"
    "\n"
    "def parse_new(p):\n"
    "    x : take(p)\n"
    "    if kind(p, \"NAME\"):\n"
    "        tn : take(p)[\"text\"]\n"
    "        while at(p, \".\"):\n"
    "            take(p)\n"
    "            tn += \".\" + need_kind(p, \"NAME\")[\"text\"]\n"
    "        if at(p, \"<\"):\n"
    "            skip_generics(p)\n"
    "        if at(p, \"[\"):\n"
    "            take(p)\n"
    "            if at(p, \"]\"):\n"
    "                take(p)\n"
    "                while at(p, \"[\"):\n"
    "                    take(p)\n"
    "                    need(p, \"]\")\n"
    "                return parse_array_init(p, x)\n"
    "            fail(p, \"sized array 'new \" + tn + \"[N]' is unsupported\", x)\n"
    "        if at(p, \"(\"):\n"
    "            take(p)\n"
    "            if not at(p, \")\"):\n"
    "                # Allow empty or reject constructor args for collections\n"
    "                if is_map_type(tn) or is_list_type(tn):\n"
    "                    fail(p, \"constructed \" + tn + \" with arguments is unsupported; use Map.of/List.of or initializer\", x)\n"
    "                depth : 1\n"
    "                while depth > 0 and not kind(p, \"END\"):\n"
    "                    tt : peek(p)[\"text\"]\n"
    "                    if tt = \"(\":\n"
    "                        depth += 1\n"
    "                    elif tt = \")\":\n"
    "                        depth += -1\n"
    "                    take(p)\n"
    "            else:\n"
    "                take(p)\n"
    "            if is_map_type(tn):\n"
    "                if at(p, \"{\"):\n"
    "                    return parse_dict_init(p, x)\n"
    "                z : node(\"Dict\", x)\n"
    "                z[\"keys\"] : []\n"
    "                z[\"values\"] : []\n"
    "                return z\n"
    "            if is_list_type(tn):\n"
    "                if at(p, \"{\"):\n"
    "                    return parse_array_init(p, x)\n"
    "                z : node(\"List\", x)\n"
    "                z[\"elts\"] : []\n"
    "                return z\n"
    "            fail(p, \"unsupported 'new \" + tn + \"(...)' expression\", x)\n"
    "        if at(p, \"{\"):\n"
    "            if is_map_type(tn):\n"
    "                return parse_dict_init(p, x)\n"
    "            return parse_array_init(p, x)\n"
    "        fail(p, \"unsupported 'new \" + tn + \"' expression\", x)\n"
    "    fail(p, \"unsupported 'new' expression\", x)\n"
    "\n"
    "def is_map_type(tn):\n"
    "    return tn = \"HashMap\" or tn = \"Map\" or tn = \"LinkedHashMap\" or tn = \"TreeMap\" or ends_with(tn, \".HashMap\") or ends_with(tn, \".Map\")\n"
    "\n"
    "def is_list_type(tn):\n"
    "    return tn = \"ArrayList\" or tn = \"List\" or tn = \"LinkedList\" or ends_with(tn, \".ArrayList\") or ends_with(tn, \".List\")\n"
    "\n"
    "def ends_with(s, suf):\n"
    "    if len(s) < len(suf):\n"
    "        return False\n"
    "    return s[len(s) - len(suf):len(s)] = suf\n"
    "\n"
    "def parse_dict_init(p, x):\n"
    "    need(p, \"{\")\n"
    "    z : node(\"Dict\", x)\n"
    "    z[\"keys\"] : []\n"
    "    z[\"values\"] : []\n"
    "    if not at(p, \"}\"):\n"
    "        while True:\n"
    "            # Java double-brace / put style is unsupported; accept {k, v} pairs like C#\n"
    "            if at(p, \"{\"):\n"
    "                take(p)\n"
    "                k : parse_expr(p)\n"
    "                need(p, \",\")\n"
    "                v : parse_expr(p)\n"
    "                need(p, \"}\")\n"
    "                z[\"keys\"].append(k)\n"
    "                z[\"values\"].append(v)\n"
    "            else:\n"
    "                fail(p, \"dictionary initializers must use {key, value} entries\", peek(p))\n"
    "            if not at(p, \",\"):\n"
    "                break\n"
    "            take(p)\n"
    "            if at(p, \"}\"):\n"
    "                break\n"
    "    need(p, \"}\")\n"
    "    return z\n"
    "\n"
    "def parse_array_init(p, x):\n"
    "    need(p, \"{\")\n"
    "    z : node(\"List\", x)\n"
    "    z[\"elts\"] : []\n"
    "    if not at(p, \"}\"):\n"
    "        while True:\n"
    "            z[\"elts\"].append(parse_expr(p))\n"
    "            if not at(p, \",\"):\n"
    "                break\n"
    "            take(p)\n"
    "            if at(p, \"}\"):\n"
    "                break\n"
    "    need(p, \"}\")\n"
    "    return z\n"
    "\n"
    "def parse_atom(p):\n"
    "    x : peek(p)\n"
    "    if kind(p, \"NUMBER\"):\n"
    "        take(p)\n"
    "        z : node(\"Const\", x)\n"
    "        z[\"value\"] : x[\"text\"]\n"
    "        z[\"kind\"] : \"number\"\n"
    "        return z\n"
    "    if kind(p, \"STRING\"):\n"
    "        take(p)\n"
    "        z : node(\"Const\", x)\n"
    "        z[\"value\"] : x[\"val\"][\"s\"]\n"
    "        z[\"kind\"] : \"string\"\n"
    "        return z\n"
    "    if at(p, \"true\") or at(p, \"false\") or at(p, \"null\"):\n"
    "        take(p)\n"
    "        z : node(\"Const\", x)\n"
    "        z[\"value\"] : \"True\" if x[\"text\"] = \"true\" else (\"False\" if x[\"text\"] = \"false\" else \"None\")\n"
    "        z[\"kind\"] : \"number\"\n"
    "        return z\n"
    "    if at(p, \"new\"):\n"
    "        return parse_new(p)\n"
    "    if kind(p, \"NAME\"):\n"
    "        take(p)\n"
    "        if is_kw(x[\"text\"]):\n"
    "            fail(p, \"unexpected keyword '\" + x[\"text\"] + \"'\", x)\n"
    "        z : node(\"Name\", x)\n"
    "        z[\"value\"] : ident(p, x)\n"
    "        x[\"text\"] : z[\"value\"]\n"
    "        return z\n"
    "    if at(p, \"(\"):\n"
    "        take(p)\n"
    "        z : parse_expr(p)\n"
    "        need(p, \")\")\n"
    "        return z\n"
    "    if at(p, \"{\"):\n"
    "        # Bare array initializer in decl context handled by parse_new; reject here\n"
    "        fail(p, \"unsupported expression\", x)\n"
    "    fail(p, \"unsupported expression\", x)\n"
    "\n"
    "def pad(n):\n"
    "    return \"    \" * n\n"
    "\n"
    "def render(ast, state):\n"
    "    state[\"comments\"] : ast[\"comments\"]\n"
    "    state[\"inline\"] : ast[\"inline\"]\n"
    "    state[\"last_comment\"] : 0\n"
    "    state[\"filename\"] : ast[\"filename\"]\n"
    "    lines : render_body(ast[\"body\"], state, 0, True)\n"
    "    for k in state[\"comments\"].keys():\n"
    "        kn : int(k)\n"
    "        if kn > state[\"last_comment\"]:\n"
    "            lines.append(state[\"comments\"][k])\n"
    "    text : \"\"\n"
    "    for line in lines:\n"
    "        if line != \"\":\n"
    "            text += line + \"\\n\"\n"
    "    return text\n"
    "\n"
    "def before_comments(st, line, indent):\n"
    "    out : []\n"
    "    for k in st[\"comments\"].keys():\n"
    "        kn : int(k)\n"
    "        if kn > st[\"last_comment\"] and kn < line:\n"
    "            out.append(pad(indent) + st[\"comments\"][k])\n"
    "            st[\"last_comment\"] : kn\n"
    "    return out\n"
    "\n"
    "def render_body(body, st, indent, doc_ok):\n"
    "    out : []\n"
    "    i : 0\n"
    "    while i < len(body):\n"
    "        s : body[i]\n"
    "        cs : before_comments(st, s[\"line\"], indent)\n"
    "        for c in cs:\n"
    "            out.append(c)\n"
    "        rs : render_stmt(s, st, indent)\n"
    "        key : str(s[\"line\"])\n"
    "        if key in st[\"inline\"] and len(rs) > 0:\n"
    "            rs[0] : rs[0] + \"  \" + st[\"inline\"][key]\n"
    "        for q in rs:\n"
    "            if q != \"\":\n"
    "                out.append(q)\n"
    "        i += 1\n"
    "    return out\n"
    "\n"
    "def render_stmt(s, st, ind):\n"
    "    p : pad(ind)\n"
    "    t : s[\"t\"]\n"
    "    if t = \"Seq\":\n"
    "        out : []\n"
    "        for c in s[\"body\"]:\n"
    "            for q in render_stmt(c, st, ind):\n"
    "                out.append(q)\n"
    "        return out\n"
    "    if t = \"Assign\":\n"
    "        return [p + target_text(s[\"target\"], st) + \" : \" + expr_text(s[\"value\"], st)]\n"
    "    if t = \"AugAssign\":\n"
    "        return [p + target_text(s[\"target\"], st) + \" \" + s[\"op\"] + \" \" + expr_text(s[\"value\"], st)]\n"
    "    if t = \"Return\":\n"
    "        return [p + (\"return\" if s[\"value\"] = None else \"return \" + expr_text(s[\"value\"], st))]\n"
    "    if t = \"break\" or t = \"continue\" or t = \"pass\":\n"
    "        return [p + t]\n"
    "    if t = \"Import\":\n"
    "        return [\"\" if s[\"erase\"] else p + \"import \" + s[\"name\"]]\n"
    "    if t = \"Expr\":\n"
    "        return [p + expr_text(s[\"value\"], st)]\n"
    "    if t = \"FunctionDef\":\n"
    "        out : []\n"
    "        for d in s[\"decorators\"]:\n"
    "            out.append(p + \"@\" + expr_text(d, st))\n"
    "        parts : []\n"
    "        i : 0\n"
    "        while i < len(s[\"args\"]):\n"
    "            q : s[\"args\"][i]\n"
    "            if s[\"defaults\"][i] != None:\n"
    "                q += \":\" + expr_text(s[\"defaults\"][i], st)\n"
    "            parts.append(q)\n"
    "            i += 1\n"
    "        out.append(p + \"def \" + s[\"name\"] + \"(\" + join_text(parts, \", \") + \"):\")\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, True):\n"
    "            out.append(q)\n"
    "        return out\n"
    "    if t = \"If\":\n"
    "        out : [p + \"if \" + expr_text(s[\"test\"], st) + \":\"]\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, False):\n"
    "            out.append(q)\n"
    "        for e in s[\"elifs\"]:\n"
    "            out.append(p + \"elif \" + expr_text(e[\"test\"], st) + \":\")\n"
    "            for q in render_body(e[\"body\"], st, ind + 1, False):\n"
    "                out.append(q)\n"
    "        if len(s[\"orelse\"]) > 0:\n"
    "            out.append(p + \"else:\")\n"
    "            for q in render_body(s[\"orelse\"], st, ind + 1, False):\n"
    "                out.append(q)\n"
    "        return out\n"
    "    if t = \"While\":\n"
    "        out : [p + \"while \" + expr_text(s[\"test\"], st) + \":\"]\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, False):\n"
    "            out.append(q)\n"
    "        return out\n"
    "    if t = \"For\":\n"
    "        out : [p + \"for \" + target_text(s[\"target\"], st) + \" in \" + expr_text(s[\"iter\"], st) + \":\"]\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, False):\n"
    "            out.append(q)\n"
    "        return out\n"
    "    return []\n"
    "\n"
    "def join_text(xs, sep):\n"
    "    out : \"\"\n"
    "    i : 0\n"
    "    while i < len(xs):\n"
    "        if i > 0:\n"
    "            out += sep\n"
    "        out += xs[i]\n"
    "        i += 1\n"
    "    return out\n"
    "\n"
    "def target_text(x, st):\n"
    "    if x[\"t\"] = \"Tuple\" or x[\"t\"] = \"List\":\n"
    "        parts : []\n"
    "        for e in x[\"elts\"]:\n"
    "            parts.append(target_text(e, st))\n"
    "        return join_text(parts, \", \")\n"
    "    return expr_text(x, st)\n"
    "\n"
    "def slice_text(x, st):\n"
    "    if x[\"t\"] = \"Slice\":\n"
    "        a : \"\" if x[\"lower\"] = None else expr_text(x[\"lower\"], st)\n"
    "        b : \"\" if x[\"upper\"] = None else expr_text(x[\"upper\"], st)\n"
    "        q : a + \":\" + b\n"
    "        if x[\"step\"] != None:\n"
    "            q += \":\" + expr_text(x[\"step\"], st)\n"
    "        return q\n"
    "    return expr_text(x, st)\n"
    "\n"
    "def expr_text(x, st):\n"
    "    t : x[\"t\"]\n"
    "    if t = \"Name\":\n"
    "        return x[\"value\"]\n"
    "    if t = \"Const\":\n"
    "        if x[\"kind\"] = \"string\":\n"
    "            return quote_string(x[\"value\"])\n"
    "        return x[\"value\"]\n"
    "    if t = \"List\":\n"
    "        parts : []\n"
    "        for e in x[\"elts\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        return \"[\" + join_text(parts, \", \") + \"]\"\n"
    "    if t = \"Dict\":\n"
    "        parts : []\n"
    "        i : 0\n"
    "        while i < len(x[\"keys\"]):\n"
    "            parts.append(expr_text(x[\"keys\"][i], st) + \": \" + expr_text(x[\"values\"][i], st))\n"
    "            i += 1\n"
    "        return \"{\" + join_text(parts, \", \") + \"}\"\n"
    "    if t = \"Attr\":\n"
    "        if x[\"attr\"] = \"length\" or x[\"attr\"] = \"Length\" or x[\"attr\"] = \"size\":\n"
    "            # .length on arrays; .size() is a call, handled in lower_call\n"
    "            if x[\"attr\"] = \"length\" or x[\"attr\"] = \"Length\":\n"
    "                return \"len(\" + expr_text(x[\"value\"], st) + \")\"\n"
    "        return expr_text(x[\"value\"], st) + \".\" + x[\"attr\"]\n"
    "    if t = \"Subscript\":\n"
    "        return expr_text(x[\"value\"], st) + \"[\" + slice_text(x[\"slice\"], st) + \"]\"\n"
    "    if t = \"Unary\":\n"
    "        return \"(\" + (\"not \" if x[\"op\"] = \"not\" else \"-\") + expr_text(x[\"value\"], st) + \")\"\n"
    "    if t = \"BinOp\":\n"
    "        if x[\"op\"] = \"+\" and (is_stringy(x[\"left\"]) or is_stringy(x[\"right\"])):\n"
    "            return \"(\" + string_operand(x[\"left\"], st) + \" + \" + string_operand(x[\"right\"], st) + \")\"\n"
    "        return \"(\" + expr_text(x[\"left\"], st) + \" \" + x[\"op\"] + \" \" + expr_text(x[\"right\"], st) + \")\"\n"
    "    if t = \"BoolOp\":\n"
    "        parts : []\n"
    "        for e in x[\"values\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        return \"(\" + join_text(parts, \" \" + x[\"op\"] + \" \") + \")\"\n"
    "    if t = \"Compare\":\n"
    "        op : \"=\" if x[\"op\"] = \"==\" else x[\"op\"]\n"
    "        return \"(\" + expr_text(x[\"left\"], st) + \" \" + op + \" \" + expr_text(x[\"right\"], st) + \")\"\n"
    "    if t = \"IfExp\":\n"
    "        return expr_text(x[\"body\"], st) + \" if \" + expr_text(x[\"test\"], st) + \" else \" + expr_text(x[\"orelse\"], st)\n"
    "    if t = \"Lambda\":\n"
    "        return \"(lambda \" + join_text(x[\"args\"], \", \") + \": \" + expr_text(x[\"body\"], st) + \")\"\n"
    "    if t = \"Call\":\n"
    "        lowered : lower_call(x, st)\n"
    "        if lowered != None:\n"
    "            return lowered\n"
    "        parts : []\n"
    "        for e in x[\"args\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        for kv in x[\"kwargs\"]:\n"
    "            parts.append(kv[0][\"text\"] + \":\" + expr_text(kv[1], st))\n"
    "        return expr_text(x[\"func\"], st) + \"(\" + join_text(parts, \", \") + \")\"\n"
    "    return \"\"\n"
    "\n"
    "def is_stringy(x):\n"
    "    if x[\"t\"] = \"Const\" and x[\"kind\"] = \"string\":\n"
    "        return True\n"
    "    if x[\"t\"] = \"BinOp\" and x[\"op\"] = \"+\" and (is_stringy(x[\"left\"]) or is_stringy(x[\"right\"])):\n"
    "        return True\n"
    "    return False\n"
    "\n"
    "def string_operand(x, st):\n"
    "    if is_stringy(x) and not (x[\"t\"] = \"BinOp\" and x[\"op\"] = \"+\"):\n"
    "        return expr_text(x, st)\n"
    "    if x[\"t\"] = \"BinOp\" and x[\"op\"] = \"+\" and (is_stringy(x[\"left\"]) or is_stringy(x[\"right\"])):\n"
    "        return expr_text(x, st)\n"
    "    return \"str(\" + expr_text(x, st) + \")\"\n"
    "\n"
    "def lower_call(x, st):\n"
    "    f : x[\"func\"]\n"
    "    # System.out.println / System.out.print\n"
    "    if f[\"t\"] = \"Attr\" and f[\"value\"][\"t\"] = \"Attr\":\n"
    "        outer : f[\"value\"]\n"
    "        if outer[\"value\"][\"t\"] = \"Name\" and outer[\"value\"][\"value\"] = \"System\" and outer[\"attr\"] = \"out\":\n"
    "            if f[\"attr\"] = \"println\" or f[\"attr\"] = \"print\":\n"
    "                parts : []\n"
    "                for e in x[\"args\"]:\n"
    "                    parts.append(expr_text(e, st))\n"
    "                return \"print(\" + join_text(parts, \", \") + \")\"\n"
    "            raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": System.out.\" + f[\"attr\"] + \" is unsupported\"\n"
    "    if f[\"t\"] = \"Attr\" and f[\"value\"][\"t\"] = \"Name\":\n"
    "        base : f[\"value\"][\"value\"]\n"
    "        name : f[\"attr\"]\n"
    "        if base = \"Math\":\n"
    "            maps : {\"max\":\"max\", \"min\":\"min\", \"abs\":\"abs\", \"sqrt\":\"sqrt\", \"exp\":\"exp\",\n"
    "                    \"log\":\"log\", \"sin\":\"sin\", \"cos\":\"cos\", \"tan\":\"tan\", \"floor\":\"floor\",\n"
    "                    \"ceil\":\"ceil\", \"pow\":\"pow\"}\n"
    "            if not name in maps:\n"
    "                raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": Math.\" + name + \" is unsupported\"\n"
    "            parts : []\n"
    "            for e in x[\"args\"]:\n"
    "                parts.append(expr_text(e, st))\n"
    "            return maps[name] + \"(\" + join_text(parts, \", \") + \")\"\n"
    "        if base = \"List\" and name = \"of\":\n"
    "            parts : []\n"
    "            for e in x[\"args\"]:\n"
    "                parts.append(expr_text(e, st))\n"
    "            return \"[\" + join_text(parts, \", \") + \"]\"\n"
    "        if base = \"Map\" and name = \"of\":\n"
    "            if len(x[\"args\"]) % 2 != 0:\n"
    "                raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": Map.of requires an even number of arguments\"\n"
    "            parts : []\n"
    "            i : 0\n"
    "            while i < len(x[\"args\"]):\n"
    "                parts.append(expr_text(x[\"args\"][i], st) + \": \" + expr_text(x[\"args\"][i + 1], st))\n"
    "                i += 2\n"
    "            return \"{\" + join_text(parts, \", \") + \"}\"\n"
    "        if name = \"size\" and len(x[\"args\"]) = 0:\n"
    "            return \"len(\" + expr_text(f[\"value\"], st) + \")\"\n"
    "        if name = \"length\" and len(x[\"args\"]) = 0:\n"
    "            return \"len(\" + expr_text(f[\"value\"], st) + \")\"\n"
    "        if name = \"get\" and len(x[\"args\"]) = 1:\n"
    "            return expr_text(f[\"value\"], st) + \"[\" + expr_text(x[\"args\"][0], st) + \"]\"\n"
    "    return None\n"
    "\n"
    "def transpile(source, filename):\n"
    "    ast : parse(source, filename)\n"
    "    return render(ast, {\"aliases\":ast[\"aliases\"]})\n"
    "\n"
    "def main():\n"
    "    return transpile_cli.run(argv, \"j2s.ie\", \"java\", transpile)\n"
    "\n"
    "# Run CLI only when this file is the entry script.\n"
    "if re_match(\"j2s\\\\.ie$\", argv[0]):\n"
    "    main()\n"
;
#endif /* SHAKTI_SHAKTI_J2S_SOURCE_H */
